def pre(vals):
    # The verifier only generates valid inputs, but we check the stated domain anyway.
    if len(vals) > 6:
        return False
    for v in vals:
        if v < -10 or v > 10:
            return False
    return True


def post(vals, result):
    # The result must be a list of the same length as the input.
    if len(result) != len(vals):
        return False
    # Track the running maximum independently and compare at each position.
    cur = 0
    for k in range(len(vals)):
        if k == 0:
            cur = vals[0]
        elif vals[k] > cur:
            cur = vals[k]
        if result[k] != cur:
            return False
    return True
